# Add the Q2 entries (credible RADEX ranges, branch test, wing constraint, physical scales) to /output/report.json. Idempotent.
import json
P='/output/report.json'; r=json.load(open(P))
r['results']=[x for x in r['results'] if not x.get('evidence','').endswith('| Q2')]
r['recipe']=[s for s in r['recipe'] if not s['description'].startswith('Q2:')]
r['caveats']=[c for c in r['caveats'] if not c.startswith('Q2:')]
if '\n\nQ2 (non-LTE' in r['interpretation']: r['interpretation']=r['interpretation'].split('\n\nQ2 (non-LTE')[0]
A=[{"name":"RADEX","value":"LAMDA hcn.dat / hco+.dat (/opt/lamda), H2 collider, Tbg 2.73 K (Tbg 5/10/20 K tested, see sensitivity entry), uniform sphere (escape probability), grids T=10-150 K (11), log n=3-8 (0.25 dex), log N/dv=13-18.5; dv=150 km/s (RADEX depends on N/dv; per-cloud dv=50 km/s -> N/3, verified q4c phys_dv_check)"},
   {"name":"data vector","value":"HCN, HCO+ 3-2/2-1 (Xb4f/Xb55 deblended), 4-3/3-2, HCN/HCO+ 3-2 (1.7\"), HCN/HCO+ 1-0 and single-line 3-2/1-0 from Harada+2018 (ApJ 855, 49) Table 13 at 1.7\"; 14% cross-band scale + deblend spread; 3-2/1-0 flux-scale nuisance (10%)"},
   {"name":"priors","value":"flat in log T, log n, log N on the grid; Tkin floor: none for the headline ranges (full grid 10-150 K; the floor-30 K variant is the old q2 run, kept only in the wing/core and H13CN/CS entries); N<=n*10^12.5 cm-2; pooled posterior = equal weight of classes A (common n, X free, filling 1), B (equal Tex, filling free), F2 (separate n for HCN/HCO+), all optically thick (tau32>1); thin classes excluded by chi2 (q4c)"}]
def add(q,v,u,c,ev,t,unit="log10 cm-3 / K / cm-2 / ratio",extra=None):
    r['results'].append({"quantity":q,"value":v,"uncertainty":u,"unit":unit,"assumptions":A+(extra or []),"confidence":c,"evidence":ev+" | Q2","target":t})

add("Q2: Credible ranges of Tkin, n(H2), N(HCN), N(HCO+), X=N(HCN)/N(HCO+), tau and Tex at the N nucleus (pooled both-thick posterior, NO temperature floor; 16-84%)",
 "Tkin 50-100 K pooled (median 80, one-sided 95% lower 40 K; no floor, grid 10-150 K) BUT class dependent: A 55-100 K, F2 50-100 K, B (equal Tex) 25-50 K (median 29); profile chi2(T) (min over n,N within class) is 19-31 for T=20-100 K and rises to 31-41 at 10-15 K and 30-33 at 150 K, so only 'Tkin ~25-100 K' is supported (T<=15 K and 150 K disfavoured, dchi2>10); log n(H2)(HCN) 4.5-5.25 (median 5.0); log N(HCN, dv=150) 15.75-16.25; log X -0.5..+0.5 (A: +0.75, B: +1.25, F2: 0.0); tau32(HCN) 5.6-18 (A 9.6-31, P(tau<3)~0); Tex ratio HCN/HCO+ 0.86 (A 0.83, B 1.06, F2 0.86); pooled chi2min 19.3 for 8 data",
 "FIT POOR at N (chi2 19-23/8 data; HCN 3-2/2-1=0.35 is 2.8 sigma below the model 0.50 in every class); grid 0.25 dex (T: 10,15,20,25,30,40,50,65,80,100,150); n,T,N degenerate; Tkin only a broad range; equal-weight pooling of classes A,B,F2 is a choice (per-class values in out/q2/sens/sens_tbg2.7_T0.csv); Tbg 2.73 K (Tbg 5 K shifts median T to 65 K, X down by 0.25 dex)",
 "low","scripts/q2_sens.py (run_q2_sens.sh) -> out/q2/sens/sens_tbg2.7_T0.csv, prof_tbg2.7_T0.csv; machinery q4c_joint.py","N nucleus (1.7-6.5\" matched beams; merges N with Bridge)")
add("Q2: Credible ranges of the same quantities at the S nucleus (pooled both-thick posterior, NO temperature floor; 16-84%)",
 "Tkin 20-30 K (median 25 K; marginal P(T=10,15 K)=0.002,0.042; one-sided 95% lower limit ~19 K; P(T>=80 K)=0.001) i.e. the earlier '30-40 K' was piled on the 30 K floor and the free-floor solution is slightly colder, not hotter; profile chi2(T) (class F2): 7.9 (30 K), 8.8 (20), 11.2 (15), 19.3 (10), 11.0 (40), 11.6 (50), 12.8 (65), 17.2 (80), 22 (100), 39 (150) -> T=15-50 K at dchi2<4, T>=80 K excluded at >~3 sigma, 10 K at ~3.4 sigma; log n(H2)(HCN) 4.5-5.5 (median 5.0; class A 4.5-5.25); log N(HCN,150) 15.5-16.75; log X -0.25..+0.75 (A +0.5, B +1.0, F2 +0.25); tau32(HCN) 5.5-58 (median 32); Tex ratio 0.63 (A 0.63, B 0.84, F2 0.63); chi2min 7.9/8 data (3 dof)",
 "classes A/F2 give T 20-30 K, class B (equal Tex, lowest weight) 10-40 K with tau32 ~10; the T=10 K cell is the grid edge; Tkin>=Tdust is not imposed (S dust Td unknown here). Tbg 2.73 K; X,n,T degenerate; one-zone RADEX",
 "low","scripts/q2_sens.py -> out/q2/sens/sens_tbg2.7_T0.csv (floors 0/15/20/30 K: sens_tbg2.7_T*.csv), prof_*.csv","S nucleus (1.7-6.5\" matched beams)")
add("Q2: Test of the T>=30 K prior floor (reviewer fix): posterior and profile likelihood in Tkin at N and S",
 "Floors 0/15/20/30 K change nothing at N (T median 80 K, P(T<=40)=0.05-0.07, P(T>=80)=0.52-0.53 for all floors). At S the floors 0/15/20 K give identical results (median 25 K; T 20-30 K, 16-84%), the 30 K floor gave 30-40 K, so the old S temperature statement was a floor artefact: correct statement is 'S: Tkin ~15-50 K (dchi2<4), >=80 K excluded (dchi2>=9), T>~15-19 K one-sided 95%'; the lower edge is set by the data (T=10 K: dchi2 11), not by a prior. The 'warmer N, colder S' contrast: pooled P(T>=80) 0.52 (N) vs 0.001 (S) BUT N class B (equal Tex) has its chi2 minimum at 30 K (19.3, same as the pooled minimum 19.26), i.e. N is also compatible with S-like T; the temperature contrast is therefore only suggestive (N T unconstrained 25-100 K; S T<~50 K)",
 "profile = min over n,N,kappa within a class; 1 parameter dchi2<4 ~2 sigma only for well-behaved likelihoods; N fit poor","medium","scripts/q2_sens.py -> out/q2/sens/prof_*.csv, sens_*.csv","N vs S",unit="K / chi2")
add("Q2: Sensitivity to the radiation field Tbg and to model assumptions (RADEX Tbg 2.73 vs 5, 10, 20 K; dust field from the 0.24\" continuum; IR pumping; hyperfine)",
 "Dust field: Xb4b 258 GHz continuum peak 0.56 (N), 1.85 mJy/beam (S) at 0.24x0.23\" -> RJ Tb 0.19 K (N), 0.62 K (S); scaled to 355 GHz (S~nu^3.5) 0.30 K (N), 1.0 K (S): Tbg,eff(beam-averaged)=3.0 K (N), 3.7 K (S), so Tbg 2.73-5 K is the relevant range (Tbg~10 K would need the dust to fill <~0.1 of the 0.24\" beam, i.e. <~5 pc scales, at 355 GHz for S; not excluded below the beam). Pooled floor-free fits: S Tbg 2.7/5/10/20 K: chi2min 7.9/7.3/16.2/24.0, T 25(20-30)/20(20-25)/20/10(grid edge) K, log X +0.25/+0.25/+0.75/+0.50; low-Tex(HCN) branch (Tex ratio<0.8) vs equal-Tex branch chi2 (class A) 9.9 vs 97 (2.7 K), 8.9 vs 59 (5 K), 27.7 vs 18.9 (10 K), 127 vs 28 (20 K): the S low-Tex branch SURVIVES for Tbg<=5 K and flips for Tbg>=10 K. N: chi2min 19.3/23.9/41.6/17.0 for Tbg 2.7/5/10/20 K; T 80(50-100)/65(25-100)/25(20-30)/10 K(edge), log X 0.0/-0.25/+1.0/+0.25; the N equal-Tex branch (A) is preferred at all Tbg (23.2/29.9/42.4/21.8 vs low-Tex 25.4/39.8/113/234); N at Tbg 10 K is disfavoured by dchi2=22 vs 2.7 K, Tbg 20 K fits with a 10 K gas (unphysical: Tkin<Tbg). Net systematic of Tbg 2.7->5 K: N T median 80->65 K (n unchanged, log X -0.25), S unchanged within the grid (T 25->20 K, n 5.0, X unchanged). IR pumping: the HCN v2=1 (14 um) vibrational line 3-2 is not detected (vib/ground Tb<0.06 N, <0.08 S, <0.13 Bridge, 3 sigma; Q4 hcn_vib.csv), consistent with weak vibrational excitation but not excluding radiative pumping of the ground ladder; hyperfine structure is not modelled (lines blended in Tb ratios at 150 km/s widths, thick-line N/dv scaling only)",
 "Tbg modelled as a blackbody (not a dilute dust field); the continuum bound is a beam-average at 0.24\" and an unresolved hot dust core is not excluded; the S branch conclusion is conditional on Tbg<=5 K; no IR-pumping model run","medium","scripts/q2_grid_tbg.py, q2_sens.py, q2_dust.py, run_q2_sens.sh -> out/q2/sens/*.csv, out/q2/q2_dust_field.csv","N, S",unit="K / chi2 / dex")
add("Q2: Per-region ratio constraints (reviewer fix 3): Bridge, outer disk, N wings, S-outflow blue lobe, with N and S for comparison -- what the data allow",
 "(a) R32=HCN/HCO+ 3-2 alone (matched beam, common n,T, X=N(HCN)/N(HCO+)=0.3-10, both thick, within 2 sigma): N core 1.05\" R=0.84: log n>=5.0 (to 7-8; median 6.3-6.8), T 10-150 K unconstrained (72% of allowed cells <=50 K); S core 0.41: log n 5-6.75 at X=1 (3.0-6.5 for X=0.3; i.e. low density only if X<=0.3), T unconstrained; Bridge 0.47+-0.03 at 1.05\": log n 4.75-7 (X=1), T unconstrained; N wings 1.35+-0.32: log n>=5.25 (X=1), T unconstrained; S-outflow blue lobe 1.2+-0.3 (Q3): log n>=5.0, T unconstrained; outer disk 6.5\" R 0.06-0.27 (zero-level dependent, resolved-out flux): log n 3-7, uninformative. One ratio = a 'n-T-X' band, no region except N/S has more. (b) Single-molecule ladders (3-2/2-1 and 4-3/3-2 from the Q1b Xb4f deblend, tau32>1, marginal 16-84%): N HCN T 50-100 K, log n 3.75-4.75; N HCO+ T 40-100, log n 3.5-4.5; S HCN T 15-50, log n 4.25-5.75; S HCO+ T 25-80, log n 3.5-4.75; Bridge HCN T 20-80, log n 4.25-6 (HCO+ 3-2/2-1=2.05+-1.5 is not physical for Tb ratios, deblend failure: unusable); outer 'disk' HCN T 20-50 K, log n 3.75-4.75 and HCO+ T 20-30, log n 3.5-4.5 (cold, sub-thermal but the 2-1 recovery/zero level is uncertain, chi2 up to 1.1). Band widths (dchi2<4) cover T 10-150 K and 2.5-5 dex in n for every region (2 data vs 3 parameters). Conclusion: the data support region-specific excitation statements only for the two nuclei (a pooled 7-datum fit); Bridge, disk and outflow have a density lower limit n>=1e5 at best from R32 and no temperature constraint",
 "R32 values are Tb ratios from the 1.05\" Xb4d product (Q1/Q9/Q3 tables), wing and outflow ratios from low S/N; the outer-disk ladder depends on the interferometric flux recovery (Q1); common n for both molecules; Tbg 2.73 K","low","scripts/q2_regions.py -> out/q2/q2_regions_R32.csv, q2_regions_ladder.csv","Bridge, disk, wings, S outflow, N, S",unit="log cm-3 / K")
add("Q2: Differential statement N vs S: which of n, Tkin, X differs? (floor-free, per class)",
 "n(H2): NOT distinguishable (log n(HCN) 4.5-5.25 N vs 4.5-5.5 S, 95% intervals overlap). Tkin: pooled median 80 K (N) vs 25 K (S) but class B at N gives 29 K and the N profile chi2 is within 3 of its minimum for 25-100 K: contrast only suggestive, S T>=80 K is excluded (dchi2>=9) while N T<=15 K is excluded (dchi2>10) - the two nuclei's allowed T ranges overlap at 25-50 K. X: not distinguishable (log X 0.0 N, +0.25 S; 95% ranges ~2 dex wide). The robust observable difference is the excitation pattern Tex(HCN)/Tex(HCO+): 0.86 (N; class B 1.06) vs 0.63 (S; classes A/F2), driven by R32 and the 1-0 ratio, valid for Tbg<=5 K. Joint two-nucleus fit with common (T,n): chi2 121.8 (4 par) vs 52.1 when the S filling differs (q4c)",
 "relative statements limited by degeneracy; N fit poor; S branch conditional on Tbg<=5 K (sensitivity entry)","low","scripts/q2_sens.py; scripts/q4c_joint.py (out/q4c/joint_summary.csv)","N vs S",unit="probability / K / log")
add("Q2: Test of the S low-n branch Tex(HCN)<Tex(HCO+) against the Q1 ladders, R32 and the published 1-0 ratio",
 "S, both-thick classes, best model per Tex-ratio branch (Tex ratio<0.8 / 0.8-1.25 / >1.25): class A chi2 9.9 / 97 / 1584; class F2 (separate n) 7.9 / 38 / 762. In the low-Tex-ratio branch all ladder/R32/R10 pulls are within 1.7 sigma (HCN 3-2/2-1 pred 0.43 vs 0.33+-0.18, HCN 4-3/3-2 0.27 vs 0.27+-0.04, HCO+ 3-2/2-1 0.60 vs 0.40+-0.11, HCO+ 4-3/3-2 0.43 vs 0.44+-0.09, R32 0.40 vs 0.39, R10 0.61 vs 0.645); the equal-Tex branch reproduces the ladders (pulls <1.0 sigma) but fails R32 (8.3 sigma, pred 0.62) and R10 (3.7 sigma). So the ladders do not contradict the low-n/Tex(HCN)<Tex(HCO+) branch, and that branch is the only both-thick one that fits R32. It corresponds to X>~3 at T~30 K, n~10^4.5 (A) or n(HCN)>n(HCO+) (F2); X<=1 is allowed only with HCN tau<~10 (P(X<1)=0.30)",
 "conditional on Tbg<=5 K: for Tbg 10/20 K the equal-Tex branch fits better (class A chi2 18.9/27.8 vs 27.7/127); ladder data have 14% cross-band scale + deblend spread (N/S ladder decomposition fits poorly at 6.5\", chi2/dof 6-16, Q9)","medium","scripts/q2_ranges.py -> out/q2/q2_branches.csv","S nucleus",unit="chi2 / sigma")
add("Q2: Velocity-resolved constraint: can a lower column in the wings reproduce the observed wing/core HCN/HCO+ 3-2 ratio?",
 "Observed wing/core (0.30\", Xb4b): N 1.07+-0.13, S 1.06+-0.12. Forward model: column 0.25-1 dex lower (f=0.56-0.1) at fixed (T,n) changes the 3-2 ratio by <~10% for optically thick lines, so this adds essentially no constraint (posterior medians unchanged: N Tkin 80 K, log n 5.0; S Tkin 30 K, log n 5.0; P(X<1) 0.48->0.52 N, 0.14->0.30 S). The data are consistent with a column-density-independent excitation across +-260 km/s; they cannot show that the wings are lower density",
 "wing columns assumed 0.25-1 dex below core with equal weight; beam mixing at 1.05\" excluded by using the 0.30\" ratios (Q9)","medium","scripts/q2_ranges.py -> out/q2/q2_ranges.csv (variants), q2_ranges.log","N, S wings",unit="ratio")
add("Q2: H13CN 4-3 and CS 7-6 as additional constraints on the RADEX solutions",
 "H13CN: predicted HCN/H13CN(4-3 Tb) for the both-thick posteriors is 17-22 (12C/13C=30), 28-36 (50), 51-68 (90) at N and S vs 3-sigma limits >8.3 (N; empirical 4.5-16) and >4 (S): 100% of draws pass for every class, so the H13CN limits do NOT constrain the solutions (they exclude only HCN tau32<~1 scenarios already excluded by the ladders, chi2 57-374 for thin classes). They would only bite with HCN/H13CN limits >~20-60. CS 7-6 (CS/HCO+ 3-2 Tb 0.051+-0.014 N, 0.056+-0.019 S): can always be matched by a CS column; implied log N(CS,150) N 15.4-15.9, S 16.0-16.7 (class A) or 15.3-15.6 (class B); log[N(HCN)/N(CS)] N 0.62 (0.48-0.73) vs S 0.11 (-0.02-0.24) in class A (S-N -0.51, 2.8 sigma) but 0.69 vs 0.57 in class B (0.6 sigma): the CS-based abundance statement is class dependent, not robust",
 "uncorrected for CS/H2CS blend (<0.34 Jy/b km/s); CS 7-6 is Band 7 4.1x2.7\" deblended, 14% scale","low","out/q4c/h13cn_pred.csv, cs_results.csv (scripts/q4c_cs.py, q4c_h13cn.py); pooled posteriors scripts/q2_ranges.py","N, S",unit="ratio")
add("Q2: Physical scales as functions of the ASSUMED X(HCN) and the CO surface-density constraint on X(HCN)",
 "Per-cloud column N(HCN, dv=50)=N(dv=150)/3: log 15.5-16.0 (N, pooled 15.3-15.8; S 15.3-16.3). N(H2)=N(HCN)/X: X=1e-9 -> log N(H2) 24.3-24.8 (N) / 24.3-25.3 (S); X=1e-8 -> 23.3-23.8 / 23.3-24.3 (log Sigma_H2 3.6-4.1 N, 3.6-4.6 S Msun/pc2); X=1e-7 -> 22.3-22.8 / 22.3-23.3 (log Sigma 2.6-3.1, 2.6-3.6); path L=N(HCN)/(X n_H2) is a function of X (out/q2/q2_scales_cond.csv per class). Constraint form: if the HCN column fills the beam, N(H2)<=Sigma_max requires X(HCN) >= N(HCN)/(Sigma_max 4.6e19): for Sigma_max=470 (CO GMC median, Brunetti+2022) log X_min=-6.8 (N; 16-84% -7.1..-6.6), -6.3 (S; -7.1..-6.1) i.e. X>~1.5e-7 N, 5e-7 S; for 1e3 -> 7e-8 / 2e-7; 3e3 -> 2.4e-8 / 8e-8; 1e4 -> 7e-9 / 2e-8 (S pooled; per-class in csv). A Galactic-like X(HCN)~1e-8 is compatible only if the nuclear Sigma_H2 >~1e4 Msun/pc2 or if the HCN-emitting source fills <<1 of the beam / the thick-line column is overestimated (n,N degenerate). NOT a finding: any statement about the dense-gas volume filling fraction (L/2R depends on the assumed X and the CO Sigma/R; the earlier 'fills <1-3% of the cloud' is withdrawn)",
 "X(HCN) is assumed (1e-9..1e-7), not measured; Sigma_max is a literature GMC value (not NGC 3256 nuclear CO at 0.3\"); 1 Msun/pc2=4.6e19 H2 cm-2 incl. He; filling 1; classes A,B,F2 shown separately in the csv, pooled equal weight","low","scripts/q2_scales_cond.py -> out/q2/q2_scales_cond.csv","N, S",unit="log cm-2 / pc / Msun pc-2")
r['recipe'].append({"order":max(s['order'] for s in r['recipe'])+1,"stage":"modelling","description":"Q2: pooled credible-range RADEX posterior (classes A,B,F2, both thick) per nucleus from the q4c grids (q4c_grid.py, q4c_joint.py), with derived Tex ratio, X, pressure, eta; Tex-ratio branch test; wing/core ratio constraint with column shifts 0.25-1 dex; physical scales for assumed X(HCN); H13CN/CS from q4c outputs.","scripts":["scripts/q4c_grid.py","scripts/q4c_joint.py","scripts/q4c_cs.py","scripts/q2_ranges.py","scripts/q2_sens.py","scripts/q2_grid_tbg.py","scripts/q2_dust.py","scripts/q2_regions.py","scripts/q2_scales_cond.py","scripts/build_report_q2.py"]})
r['interpretation']+=("\n\nQ2 (non-LTE ranges; credible intervals, not best fits; revised after the temperature-floor and Tbg tests): both nuclei are described by optically thick (tau32 HCN ~5-50), sub-thermal HCN and HCO+ (Tex 6-11 K, Tkin>>Tex) in gas of log n(H2)~4.5-5.5 (3e4-3e5 cm-3) with column degeneracies of ~0.5 dex. Density is not distinguishable between N and S. With no temperature floor S is Tkin ~15-50 K (T>=80 K excluded at >3 sigma) and N is 25-100 K (class dependent; a warmer N is only suggestive). The robust N/S difference is the excitation pattern: Tex(HCN)/Tex(HCO+)~0.86 at N vs 0.63 at S (the only both-thick solution that reproduces R32=0.39 and the 1-0 ratio), valid for a background Tbg<=5 K (continuum-based Tbg,eff 3.0-3.7 K); for Tbg>=10 K the equal-Tex solution is preferred at S. Bridge, disk, wing and outflow regions have only one or two ratios: R32 alone gives n>=1e5 cm-3 and no temperature constraint, and the single-molecule ladders are band-degenerate (T 10-150 K, 2.5-5 dex in n). Abundances: X(HCN) is not measured; the CO surface density demands X(HCN)>~1e-7 (Sigma_max 470 Msun/pc2) or >~1e-8 (Sigma 1e4) if the HCN column fills the beam. The H13CN limits and the velocity-resolved ratios do not add constraints; CS is class dependent.")
r['caveats'].append("Q2: RADEX is a one-zone uniform-sphere model on a 0.25 dex grid; the N fit is poor (chi2 19-23/8), the temperature floor was removed (S Tkin 15-50 K, N 25-100 K), X, n, T and filling are degenerate, N(HCN) per cloud depends on an assumed dv and X(HCN), and the ladder/1-0 data carry a 14%/5% cross-band systematic (Harada 1-0 at 1.7\" taken from the paper). Only ranges should be quoted; a two-phase (dense+diffuse) model, HCN IR pumping and chemistry-dependent abundances are not modelled. Disk and outflow regions have no matched multi-J ladders in the data.")
json.dump(r,open(P,'w'),indent=1)
